#include "fractal/local_workspace_service.h"
#include <assert.h>
#include <string.h>
static fractal_intent_id idn(uint64_t n){fractal_intent_id id={0x1234u,n};return id;}
static fractal_client_intent mk(fractal_local_service*s,fractal_participant_id p,uint64_t seq,fractal_client_intent_kind k){fractal_client_intent i;memset(&i,0,sizeof(i));i.contract_version=FRACTAL_WORKSPACE_CONTRACT_VERSION;i.workspace_id=s->workspace.id;i.participant_id=p;i.expected_revision=s->workspace.revision;i.command_sequence=seq;i.kind=k;i.identity=idn(seq);return i;}
int main(void){fractal_local_service s;fractal_participant_id p;fractal_client_intent i;fractal_local_transition_result r;fractal_reacquire_request q;fractal_reacquire_response a;fractal_local_service_init(&s,1);assert(fractal_local_service_open(&s)==0);assert(s.lifetime.state==FRACTAL_WS_OPEN);assert(fractal_local_service_open_session(&s,fractal_local_operator_admit_current_user(),&p)==0);i=mk(&s,p,1,FRACTAL_INTENT_ACQUIRE_LEASE);r=fractal_local_service_apply_intent(&s,&i);assert(r.transition.accepted);i=mk(&s,p,2,FRACTAL_INTENT_SET_ITERATION_BUDGET);i.payload.unsigned_value=99;r=fractal_local_service_apply_intent(&s,&i);assert(r.transition.accepted&&r.transition.generation_created);memset(&q,0,sizeof(q));q.contract_version=FRACTAL_REACQUIRE_CONTRACT_VERSION;q.service_id=s.service_id;q.participant_id=p;q.workspace_id=s.workspace.id;q.last_accepted_workspace_revision=1;q.last_known_generation=0;a=fractal_local_service_reacquire(&s,&q);assert(a.kind==FRACTAL_REACQUIRE_FULL_SNAPSHOT);return 0;}
